def describe_omniscient_engineering_framework() -> str:
    lines = [
        "TitanAI Omniscient Engineering Framework Era",
        "",
        "This era represents the transition from an eternal software guardian into a complete technology intelligence framework that understands why systems exist, how they interact, and how they should evolve.",
        "",
    ]
    for capability in OMNISCIENT_ENGINEERING_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
